-- -----------------------------------------------------
-- procedure create_wallet
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`create_wallet`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE create_wallet(
    IN p_wallet_type ENUM('user','provider','organization','system','virtual','business'),
    IN p_wallet_currency ENUM('DZD','USD','EUR'),
    IN p_wallet_owner_id INT
)
BEGIN
    DECLARE new_wallet_id INT;
    
    INSERT INTO wallet (
        wallet_type,
        wallet_currency,
        wallet_balance,
        wallet_status
    ) VALUES (
        p_wallet_type,
        p_wallet_currency,
        0.00,
        'pending_verification'
    );
    
    SET new_wallet_id = LAST_INSERT_ID();
    
    -- If owner_id is provided, create association
    IF p_wallet_owner_id IS NOT NULL AND p_wallet_owner_id > 0 THEN
        -- Store owner reference in a separate table or update the owner's table
        -- This depends on your schema structure
        CASE p_wallet_type
            WHEN 'user' THEN
                UPDATE app_user SET app_user_wallet_id = new_wallet_id 
                WHERE id_app_user = p_wallet_owner_id;
            WHEN 'provider' THEN
                UPDATE product_provider SET product_provider_wallet_id = new_wallet_id 
                WHERE id_product_provider = p_wallet_owner_id;
            WHEN 'organization' THEN
                UPDATE provider_organisation SET provider_organisation_wallet_id = new_wallet_id 
                WHERE idprovider_organisation = p_wallet_owner_id;
        END CASE;
    END IF;
    
    SELECT new_wallet_id AS wallet_id;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function get_wallet_balance
-- -----------------------------------------------------

USE `verdelia`;
DROP function IF EXISTS `verdelia`.`get_wallet_balance`;

DELIMITER $$
USE `verdelia`$$
CREATE FUNCTION get_wallet_balance(p_wallet_id INT)
RETURNS DOUBLE
DETERMINISTIC
READS SQL DATA
BEGIN
    DECLARE balance DOUBLE;
    
    SELECT wallet_balance INTO balance
    FROM wallet
    WHERE id_wallet = p_wallet_id;
    
    RETURN COALESCE(balance, 0.00);
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function is_wallet_valid
-- -----------------------------------------------------

USE `verdelia`;
DROP function IF EXISTS `verdelia`.`is_wallet_valid`;

DELIMITER $$
USE `verdelia`$$
CREATE FUNCTION is_wallet_valid(p_wallet_id INT)
RETURNS BOOLEAN
DETERMINISTIC
READS SQL DATA
BEGIN
    DECLARE valid BOOLEAN;
    DECLARE wallet_status VARCHAR(50);
    
    SELECT wallet_status INTO wallet_status
    FROM wallet
    WHERE id_wallet = p_wallet_id;
    
    SET valid = (wallet_status IN ('active', 'pending_verification'));
    
    RETURN valid;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure process_payment
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`process_payment`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE process_payment(
    IN p_payment_invoice_id INT,
    IN p_payment_amount DECIMAL(15,4),
    IN p_payment_method ENUM('cash','card','bank_transfer','mobile_money','crypto','deposit','wallet','check'),
    IN p_payment_reference VARCHAR(255),
    IN p_payment_notes TEXT,
    IN p_payment_type ENUM('deposit','payment','refund')
)
BEGIN
    DECLARE new_payment_id INT;
    DECLARE invoice_total DECIMAL(15,4);
    DECLARE invoice_paid DECIMAL(15,4);
    DECLARE new_status VARCHAR(50);
    
    -- Start transaction
    START TRANSACTION;
    
    -- Validate invoice exists
    SELECT invoice_total_amount INTO invoice_total
    FROM invoice
    WHERE invoice_id = p_payment_invoice_id
    FOR UPDATE;
    
    IF invoice_total IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invoice not found';
    END IF;
    
    -- Calculate total paid for this invoice
    SELECT COALESCE(SUM(payment_amount), 0) INTO invoice_paid
    FROM payment
    WHERE payment_invoice_id = p_payment_invoice_id
    AND payment_status != 'cancelled';
    
    -- Determine new invoice status
    IF (invoice_paid + p_payment_amount) >= invoice_total THEN
        SET new_status = 'paid';
    ELSEIF invoice_paid + p_payment_amount > 0 THEN
        SET new_status = 'partially_paid';
    ELSE
        SET new_status = 'unpaid';
    END IF;
    
    -- Create payment record
    INSERT INTO payment (
        payment_invoice_id,
        payment_amount,
        payment_method,
        payment_status,
        payment_reference,
        payment_notes,
        payment_type,
        payment_created_at,
        payment_updated_at
    ) VALUES (
        p_payment_invoice_id,
        p_payment_amount,
        p_payment_method,
        'completed',
        p_payment_reference,
        p_payment_notes,
        p_payment_type,
        NOW(),
        NOW()
    );
    
    SET new_payment_id = LAST_INSERT_ID();
    
    -- Update invoice status
    UPDATE invoice
    SET invoice_status = new_status,
        invoice_updated_at = NOW()
    WHERE invoice_id = p_payment_invoice_id;
    
    COMMIT;
    
    SELECT new_payment_id AS payment_id;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure create_money_transaction
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`create_money_transaction`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE create_money_transaction(
    IN p_source_wallet_id INT,
    IN p_destination_wallet_id INT,
    IN p_amount DOUBLE,
    IN p_reference VARCHAR(255),
    IN p_document_url VARCHAR(255),
    IN p_payment_id INT
)
BEGIN
    DECLARE new_transaction_id INT;
    DECLARE source_balance DOUBLE;
    DECLARE source_status VARCHAR(50);
    DECLARE dest_status VARCHAR(50);
    
    -- Start transaction
    START TRANSACTION;
    
    -- Validate source wallet
    SELECT wallet_balance, wallet_status INTO source_balance, source_status
    FROM wallet
    WHERE id_wallet = p_source_wallet_id
    FOR UPDATE;
    
    IF source_balance IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Source wallet not found';
    END IF;
    
    IF source_status != 'active' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Source wallet is not active';
    END IF;
    
    IF source_balance < p_amount THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Insufficient balance in source wallet';
    END IF;
    
    -- Validate destination wallet
    SELECT wallet_status INTO dest_status
    FROM wallet
    WHERE id_wallet = p_destination_wallet_id
    FOR UPDATE;
    
    IF dest_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Destination wallet not found';
    END IF;
    
    IF dest_status != 'active' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Destination wallet is not active';
    END IF;
    
    -- Create transaction record
    INSERT INTO money_transaction (
        money_transaction_amount,
        money_transaction_reference,
        money_transaction_document_url,
        money_transaction_wallet_source_id,
        money_transaction_wallet_destination_id,
        money_transaction_status,
        money_transaction_for_payment,
        money_transaction_creation,
        money_transaction_last_updated
    ) VALUES (
        p_amount,
        p_reference,
        p_document_url,
        p_source_wallet_id,
        p_destination_wallet_id,
        'completed',
        p_payment_id,
        NOW(),
        NOW()
    );
    
    SET new_transaction_id = LAST_INSERT_ID();
    
    -- Update source wallet balance
    UPDATE wallet
    SET wallet_balance = wallet_balance - p_amount
    WHERE id_wallet = p_source_wallet_id;
    
    -- Update destination wallet balance
    UPDATE wallet
    SET wallet_balance = wallet_balance + p_amount
    WHERE id_wallet = p_destination_wallet_id;
    
    COMMIT;
    
    SELECT new_transaction_id AS transaction_id;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure process_refund
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`process_refund`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE process_refund(
    IN p_original_transaction_id INT,
    IN p_refund_amount DOUBLE,
    IN p_refund_reason VARCHAR(255)
)
BEGIN
    DECLARE original_source INT;
    DECLARE original_destination INT;
    DECLARE original_amount DOUBLE;
    DECLARE original_status VARCHAR(50);
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get original transaction details
    SELECT 
        money_transaction_wallet_source_id,
        money_transaction_wallet_destination_id,
        money_transaction_amount,
        money_transaction_status
    INTO 
        original_source,
        original_destination,
        original_amount,
        original_status
    FROM money_transaction
    WHERE id_money_transaction = p_original_transaction_id
    FOR UPDATE;
    
    IF original_source IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Original transaction not found';
    END IF;
    
    IF original_status = 'refunded' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Transaction already refunded';
    END IF;
    
    -- Validate refund amount
    IF p_refund_amount > original_amount THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Refund amount exceeds original transaction amount';
    END IF;
    
    -- Create refund transaction (reverse direction)
    INSERT INTO money_transaction (
        money_transaction_amount,
        money_transaction_reference,
        money_transaction_wallet_source_id,
        money_transaction_wallet_destination_id,
        money_transaction_status,
        money_transaction_document_url,
        money_transaction_creation,
        money_transaction_last_updated
    ) VALUES (
        p_refund_amount,
        CONCAT('REFUND_', p_original_transaction_id),
        original_destination,
        original_source,
        'completed',
        NULL,
        NOW(),
        NOW()
    );
    
    -- Update source wallet balance (original destination)
    UPDATE wallet
    SET wallet_balance = wallet_balance - p_refund_amount
    WHERE id_wallet = original_destination;
    
    -- Update destination wallet balance (original source)
    UPDATE wallet
    SET wallet_balance = wallet_balance + p_refund_amount
    WHERE id_wallet = original_source;
    
    -- Mark original transaction as refunded
    UPDATE money_transaction
    SET money_transaction_status = 'refunded',
        money_transaction_last_updated = NOW()
    WHERE id_money_transaction = p_original_transaction_id;
    
    COMMIT;
END$$

DELIMITER ;

