    IN p_wallet_id INT,
    IN p_amount DOUBLE,
    IN p_reference VARCHAR(255),
    IN p_payment_id INT
)
BEGIN
    -- System wallet as source (virtual system account)
    -- You'll need a system wallet ID, e.g., 1
    DECLARE system_wallet_id INT DEFAULT 1;
    
    CALL create_money_transaction(
        system_wallet_id,
        p_wallet_id,
        p_amount,
        p_reference,
