-- -----------------------------------------------------
-- procedure get_wallet_transactions
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`get_wallet_transactions`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE get_wallet_transactions(
    IN p_wallet_id INT,
    IN p_limit INT,
    IN p_offset INT
)
BEGIN
    SELECT 
        mt.id_money_transaction,
        mt.money_transaction_amount,
        mt.money_transaction_reference,
        mt.money_transaction_status,
        mt.money_transaction_creation,
        mt.money_transaction_document_url,
        mt.money_transaction_for_payment,
        -- Source wallet info
        source_wallet.id_wallet AS source_wallet_id,
        source_wallet.wallet_type AS source_wallet_type,
        -- Destination wallet info
        dest_wallet.id_wallet AS dest_wallet_id,
        dest_wallet.wallet_type AS dest_wallet_type,
        -- Payment info if exists
        p.payment_id,
        p.payment_amount,
        p.payment_method,
        p.payment_status
    FROM money_transaction mt
    LEFT JOIN wallet source_wallet ON mt.money_transaction_wallet_source_id = source_wallet.id_wallet
    LEFT JOIN wallet dest_wallet ON mt.money_transaction_wallet_destination_id = dest_wallet.id_wallet
    LEFT JOIN payment p ON mt.money_transaction_for_payment = p.payment_id
    WHERE mt.money_transaction_wallet_source_id = p_wallet_id
       OR mt.money_transaction_wallet_destination_id = p_wallet_id
    ORDER BY mt.money_transaction_creation DESC
    LIMIT p_limit OFFSET p_offset;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure get_wallet_summary
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`get_wallet_summary`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE get_wallet_summary(
    IN p_wallet_id INT
)
BEGIN
    DECLARE balance DOUBLE;
    DECLARE total_in DOUBLE;
    DECLARE total_out DOUBLE;
    DECLARE pending_in DOUBLE;
    DECLARE pending_out DOUBLE;
    
    -- Get current balance
    SELECT wallet_balance INTO balance
    FROM wallet
    WHERE id_wallet = p_wallet_id;
    
    -- Calculate totals
    SELECT 
        COALESCE(SUM(CASE 
            WHEN money_transaction_wallet_destination_id = p_wallet_id 
            AND money_transaction_status = 'completed' 
            THEN money_transaction_amount 
            ELSE 0 
        END), 0) INTO total_in
    FROM money_transaction;
    
    SELECT 
        COALESCE(SUM(CASE 
            WHEN money_transaction_wallet_source_id = p_wallet_id 
            AND money_transaction_status = 'completed' 
            THEN money_transaction_amount 
            ELSE 0 
        END), 0) INTO total_out
    FROM money_transaction;
    
    SELECT 
        COALESCE(SUM(CASE 
            WHEN money_transaction_wallet_destination_id = p_wallet_id 
            AND money_transaction_status = 'pending' 
            THEN money_transaction_amount 
            ELSE 0 
        END), 0) INTO pending_in
    FROM money_transaction;
    
    SELECT 
        COALESCE(SUM(CASE 
            WHEN money_transaction_wallet_source_id = p_wallet_id 
            AND money_transaction_status = 'pending' 
            THEN money_transaction_amount 
            ELSE 0 
        END), 0) INTO pending_out
    FROM money_transaction;
    
    -- Return summary
    SELECT 
        balance AS current_balance,
        total_in AS total_credited,
        total_out AS total_debited,
        (total_in - total_out) AS net_balance,
        pending_in AS pending_credits,
        pending_out AS pending_debits,
        (pending_in - pending_out) AS pending_net;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure reverse_transaction
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`reverse_transaction`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE reverse_transaction(
    IN p_transaction_id INT,
    IN p_reason VARCHAR(255)
)
BEGIN
    DECLARE source_id INT;
    DECLARE dest_id INT;
    DECLARE amount DOUBLE;
    DECLARE current_status VARCHAR(50);
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get transaction details
    SELECT 
        money_transaction_wallet_source_id,
        money_transaction_wallet_destination_id,
        money_transaction_amount,
        money_transaction_status
    INTO 
        source_id,
        dest_id,
        amount,
        current_status
    FROM money_transaction
    WHERE id_money_transaction = p_transaction_id
    FOR UPDATE;
    
    IF source_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Transaction not found';
    END IF;
    
    IF current_status != 'completed' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Only completed transactions can be reversed';
    END IF;
    
    -- Reverse the transaction
    INSERT INTO money_transaction (
        money_transaction_amount,
        money_transaction_reference,
        money_transaction_wallet_source_id,
        money_transaction_wallet_destination_id,
        money_transaction_status,
        money_transaction_document_url,
        money_transaction_creation,
        money_transaction_last_updated
    ) VALUES (
        amount,
        CONCAT('REVERSAL_', p_transaction_id),
        dest_id,
        source_id,
        'completed',
        NULL,
        NOW(),
        NOW()
    );
    
    -- Update wallet balances
    UPDATE wallet SET wallet_balance = wallet_balance - amount 
    WHERE id_wallet = dest_id;
    
    UPDATE wallet SET wallet_balance = wallet_balance + amount 
    WHERE id_wallet = source_id;
    
    -- Mark original as reversed
    UPDATE money_transaction
    SET money_transaction_status = 'reversed',
        money_transaction_last_updated = NOW()
    WHERE id_money_transaction = p_transaction_id;
    
    COMMIT;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function get_invoice_payment_status
-- -----------------------------------------------------

USE `verdelia`;
DROP function IF EXISTS `verdelia`.`get_invoice_payment_status`;

DELIMITER $$
USE `verdelia`$$
CREATE FUNCTION get_invoice_payment_status(p_invoice_id INT)
RETURNS VARCHAR(50)
DETERMINISTIC
READS SQL DATA
BEGIN
    DECLARE total DECIMAL(15,4);
    DECLARE paid DECIMAL(15,4);
    DECLARE status VARCHAR(50);
    
    SELECT invoice_total_amount INTO total
    FROM invoice
    WHERE invoice_id = p_invoice_id;
    
    SELECT COALESCE(SUM(payment_amount), 0) INTO paid
    FROM payment
    WHERE payment_invoice_id = p_invoice_id
    AND payment_status != 'cancelled';
    
    IF paid = 0 THEN
        SET status = 'unpaid';
    ELSEIF paid >= total THEN
        SET status = 'paid';
    ELSE
        SET status = 'partially_paid';
    END IF;
    
    RETURN status;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure process_cart_payment
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`process_cart_payment`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE process_cart_payment(
    IN p_cart_id INT,
    IN p_payment_method ENUM('cash','card','bank_transfer','mobile_money','crypto','deposit','wallet','check'),
    IN p_amount DECIMAL(15,4),
    IN p_payment_reference VARCHAR(255)
)
BEGIN
    DECLARE invoice_id INT;
    DECLARE payment_id INT;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Get or create invoice for cart
    SELECT cart_invoice INTO invoice_id
    FROM cart
    WHERE cart_id = p_cart_id;
    
    IF invoice_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cart has no invoice';
    END IF;
    
    -- Process payment
    CALL process_payment(
        invoice_id,
        p_amount,
        p_payment_method,
        p_payment_reference,
        CONCAT('Payment for cart #', p_cart_id),
        'payment'
    );
    
    -- Get the payment ID
    SET payment_id = LAST_INSERT_ID();
    
    -- Update cart status
    UPDATE cart
    SET cart_status = 'completed',
        cart_updated_at = NOW()
    WHERE cart_id = p_cart_id;
    
    COMMIT;
    
    SELECT payment_id AS payment_id;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure create_ordered_service
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`create_ordered_service`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE  create_ordered_service(
    IN p_cart_id INT,
    IN p_service_id INT,
    IN p_quantity INT,
    IN p_unit_price DECIMAL(15,4),
    IN p_total_price DECIMAL(15,4),
    IN p_notes TEXT,
    IN p_scheduled_at TIMESTAMP,
    IN p_delivery_fee DOUBLE,
    IN p_delivery_status VARCHAR(50),
    OUT p_ordered_service_id INT,
    OUT p_success BOOLEAN,
    OUT p_error_message VARCHAR(255)
)
BEGIN
    DECLARE v_service_exists INT DEFAULT 0;
    DECLARE v_is_active TINYINT DEFAULT 0;
    DECLARE v_cart_exists INT DEFAULT 0;
    DECLARE v_cart_status VARCHAR(50) DEFAULT '';
    
    -- Declare exit handler for errors
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            p_error_message = MESSAGE_TEXT;
        SET p_success = FALSE;
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = '...';
    END;
    
    -- Start transaction
    START TRANSACTION;
    
    -- Initialize output
    SET p_success = FALSE;
    SET p_error_message = '';
    SET p_ordered_service_id = 0;
    
    -- Validate cart exists and is in valid status
    SELECT COUNT(*) INTO v_cart_exists
    FROM cart
    WHERE cart_id = p_cart_id;
    
    IF v_cart_exists = 0 THEN
        SET p_error_message = 'Cart not found';
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
		SET MESSAGE_TEXT = 'Cart not found';
    END IF;
    
    -- Get cart status
    SELECT cart_status INTO v_cart_status
    FROM cart
    WHERE cart_id = p_cart_id;
    
    -- Check if cart status is valid (using the actual status values in your DB)
    IF v_cart_status NOT IN ('PENDING', 'OPEN', 'CHECKOUT', 'pending', 'open', 'checkout') THEN
        SET p_error_message = CONCAT('Cart is not in a valid status for adding services. Current status: ', v_cart_status);
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cart not found';
        ROLLBACK;
    END IF;
    
    -- Validate service exists and is active
SELECT provided_service_is_active
INTO v_is_active
FROM provided_service
WHERE provided_service_id = p_service_id
LIMIT 1;
    
    IF v_service_exists = 0 THEN
        SET p_error_message = 'Service not found';
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cart not found';
    END IF;
    
    IF v_is_active = 0 OR v_is_active IS NULL THEN
        SET p_error_message = 'Service is not active';
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cart not found';
    END IF;
    
    
    
    -- Validate total price is valid
    IF p_total_price < 0 THEN
        SET p_error_message = 'Total price cannot be negative';
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cart not found';
    END IF;
    
    IF p_quantity <= 0 THEN
        SET p_error_message = 'Quantity must be greater than 0';
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'Cart not found';
    END IF;
    
    -- Create ordered service
    INSERT INTO ordered_service (
        ordered_service_cart_id,
        ordered_service_service_id,
        ordered_service_quantity,
        ordered_service_unit_price,
        ordered_service_total_price,
        ordered_service_notes,
        ordered_service_scheduled_at,
        ordered_service_delivery_fee,
        ordered_service_delivery_status
    ) VALUES (
        p_cart_id,
        p_service_id,
        p_quantity,
        p_unit_price,
        p_total_price,
        p_notes,
        p_scheduled_at,
        COALESCE(p_delivery_fee, 0),
        COALESCE(p_delivery_status, 'PENDING')
    );
    
    SET p_ordered_service_id = LAST_INSERT_ID();
    
    -- Update cart total amount
    UPDATE cart
    SET cart_total_amount = COALESCE(cart_total_amount, 0) + p_total_price,
        cart_updated_at = NOW()
    WHERE cart_id = p_cart_id;
    
    SET p_success = TRUE;
    
    COMMIT;
    
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure cancel_ordered_service
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`cancel_ordered_service`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE cancel_ordered_service(
    IN p_ordered_service_id INT,
    IN p_cancellation_reason VARCHAR(255),
    OUT p_success BOOLEAN,
    OUT p_error_message VARCHAR(255)
)
BEGIN

    DECLARE v_current_status VARCHAR(50);
    DECLARE v_cart_id INT;
    DECLARE v_service_price DECIMAL(15,4);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        SET p_success = FALSE;
        SET p_error_message = 'Transaction failed';
        ROLLBACK;
    END;

    START TRANSACTION;

    SET p_success = FALSE;
    SET p_error_message = '';

    SELECT
        ordered_service_delivery_status,
        ordered_service_cart_id,
        ordered_service_total_price
    INTO
        v_current_status,
        v_cart_id,
        v_service_price
    FROM ordered_service
    WHERE ordered_service_id = p_ordered_service_id
    FOR UPDATE;

    IF v_current_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Ordered service not found';
    END IF;

    IF v_current_status = 'cancelled' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Already cancelled';
    END IF;

    IF v_current_status NOT IN ('pending','processing','scheduled') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid status for cancellation';
    END IF;

    UPDATE ordered_service
    SET ordered_service_delivery_status = 'cancelled',
        ordered_service_notes = CONCAT(
            COALESCE(ordered_service_notes,''),
            ' | Cancelled: ',
            COALESCE(p_cancellation_reason,'No reason provided')
        ),
        ordered_service_updated_at = NOW()
    WHERE ordered_service_id = p_ordered_service_id;

    UPDATE cart
    SET cart_total_amount =
        GREATEST(cart_total_amount - v_service_price, 0),
        cart_updated_at = NOW()
    WHERE cart_id = v_cart_id;

    CALL restore_service_resources(p_ordered_service_id);

    COMMIT;

    SET p_success = TRUE;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure restore_service_resources
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`restore_service_resources`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE restore_service_resources(
    IN p_ordered_service_id INT
)
BEGIN
    DECLARE v_service_id INT;
    DECLARE v_quantity INT;
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_product_id INT;
    DECLARE v_quantity_to_restore INT;
    
    DECLARE cur_resources CURSOR FOR
        SELECT 
            srr.service_resource_requirement_product_ref,
            srr.service_resource_requirement_quantity * os.ordered_service_quantity
        FROM service_resource_requirement srr
        JOIN ordered_service os ON srr.service_resource_requirement_service_id = os.ordered_service_service_id
        WHERE os.ordered_service_id = p_ordered_service_id
        AND srr.service_resource_requirement_is_consumable = 1
        AND srr.service_resource_requirement_product_ref IS NOT NULL;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    -- Get the service and quantity for this ordered service
    SELECT 
        ordered_service_service_id,
        ordered_service_quantity
    INTO 
        v_service_id,
        v_quantity
    FROM ordered_service
    WHERE ordered_service_id = p_ordered_service_id;
    
    -- Restore stock for each consumable resource
    OPEN cur_resources;
    
    read_loop: LOOP
        FETCH cur_resources INTO v_product_id, v_quantity_to_restore;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        -- Restore product stock
        UPDATE product
        SET product_quantity = product_quantity + v_quantity_to_restore
        WHERE id_product = v_product_id;
        
    END LOOP;
    
    CLOSE cur_resources;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure create_ordered_item
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`create_ordered_item`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE create_ordered_item(
    IN p_cart_id INT,
    IN p_product_id INT,
    IN p_quantity INT,
    IN p_applied_vat DOUBLE,
    IN p_unit_price DOUBLE,
    IN p_product_discount DOUBLE,
    IN p_delivery_fee DOUBLE,
    IN p_delivery_status VARCHAR(50),
    OUT p_ordered_item_id INT,
    OUT p_success BOOLEAN,
    OUT p_error_message VARCHAR(255)
)
BEGIN

    DECLARE v_product_quantity INT;
    DECLARE v_product_price DOUBLE;
    DECLARE v_cart_status VARCHAR(50);
    DECLARE v_total_price DOUBLE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            p_error_message = MESSAGE_TEXT;

        SET p_success = FALSE;

        ROLLBACK;
    END;

    START TRANSACTION;

    SET p_success = FALSE;
    SET p_error_message = '';
    SET p_ordered_item_id = NULL;

    SELECT cart_status
    INTO v_cart_status
    FROM cart
    WHERE cart_id = p_cart_id
    FOR UPDATE;

    IF v_cart_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cart not found';
    END IF;

    IF LOWER(v_cart_status) NOT IN ('open','pending','checkout') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cart is not in a valid status for adding items';
    END IF;

    SELECT
        product_quantity,
        product_price
    INTO
        v_product_quantity,
        v_product_price
    FROM product
    WHERE id_product = p_product_id
    FOR UPDATE;

    IF v_product_quantity IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Product not found';
    END IF;

    IF p_quantity <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Quantity must be greater than zero';
    END IF;

    IF v_product_quantity < p_quantity THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Insufficient stock';
    END IF;

    SET v_total_price =
        (p_unit_price * p_quantity)
        * (1 + p_applied_vat / 100)
        - (p_product_discount * p_quantity);

    INSERT INTO ordered_item (
        ordered_product_id,
        ordered_quantity,
        applied_vat,
        unit_price,
        product_discount,
        ordered_item_cart_ref,
        ordered_item_delivery_status,
        ordered_item_delivery_fee
    )
    VALUES (
        p_product_id,
        p_quantity,
        p_applied_vat,
        p_unit_price,
        p_product_discount,
        p_cart_id,
        COALESCE(p_delivery_status, 'pending'),
        COALESCE(p_delivery_fee, 0)
    );

    SET p_ordered_item_id = LAST_INSERT_ID();

    UPDATE product
    SET product_quantity = product_quantity - p_quantity,
        last_updated = NOW()
    WHERE id_product = p_product_id;

    UPDATE cart
    SET cart_total_amount =
        COALESCE(cart_total_amount, 0) + v_total_price,
        cart_updated_at = NOW()
    WHERE cart_id = p_cart_id;

    COMMIT;

    SET p_success = TRUE;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure cancel_ordered_item
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`cancel_ordered_item`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE cancel_ordered_item(
    IN p_ordered_item_id INT,
    IN p_cancellation_reason VARCHAR(255),
    OUT p_success BOOLEAN,
    OUT p_error_message VARCHAR(255)
)
BEGIN

    DECLARE v_product_id INT;
    DECLARE v_quantity INT;
    DECLARE v_unit_price DOUBLE;
    DECLARE v_product_discount DOUBLE;
    DECLARE v_applied_vat DOUBLE;
    DECLARE v_cart_id INT;
    DECLARE v_current_status VARCHAR(50);
    DECLARE v_total_price DOUBLE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            p_error_message = MESSAGE_TEXT;

        SET p_success = FALSE;
        ROLLBACK;
    END;

    START TRANSACTION;

    SET p_success = FALSE;
    SET p_error_message = '';

    -- Lock ordered item row
    SELECT
        ordered_product_id,
        ordered_quantity,
        unit_price,
        product_discount,
        applied_vat,
        ordered_item_cart_ref,
        ordered_item_delivery_status
    INTO
        v_product_id,
        v_quantity,
        v_unit_price,
        v_product_discount,
        v_applied_vat,
        v_cart_id,
        v_current_status
    FROM ordered_item
    WHERE id_ordered_item = p_ordered_item_id
    FOR UPDATE;

    IF v_product_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Ordered item not found';
    END IF;

    IF v_current_status = 'cancelled' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Item already cancelled';
    END IF;

    IF v_current_status NOT IN ('pending', 'processing') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Item cannot be cancelled in current status';
    END IF;

    SET v_total_price =
        (v_unit_price * v_quantity)
        * (1 + v_applied_vat / 100)
        - (v_product_discount * v_quantity);

    UPDATE ordered_item
    SET ordered_item_delivery_status = 'cancelled'
    WHERE id_ordered_item = p_ordered_item_id;

    UPDATE product
    SET product_quantity = product_quantity + v_quantity,
        last_updated = NOW()
    WHERE id_product = v_product_id;

    UPDATE cart
    SET cart_total_amount =
        GREATEST(cart_total_amount - v_total_price, 0),
        cart_updated_at = NOW()
    WHERE cart_id = v_cart_id;

    COMMIT;

    SET p_success = TRUE;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure restore_ordered_item_stock
-- -----------------------------------------------------

USE `verdelia`;
DROP procedure IF EXISTS `verdelia`.`restore_ordered_item_stock`;

DELIMITER $$
USE `verdelia`$$
CREATE PROCEDURE restore_ordered_item_stock(
    IN p_ordered_item_id INT
)
BEGIN
    DECLARE v_product_id INT;
    DECLARE v_quantity INT;
    
    -- Get product and quantity
    SELECT 
        ordered_product_id,
        ordered_quantity
    INTO 
        v_product_id,
        v_quantity
    FROM ordered_item
    WHERE id_ordered_item = p_ordered_item_id;
    
    -- Restore stock
    UPDATE product
    SET product_quantity = product_quantity + v_quantity,
        last_updated = NOW()
    WHERE id_product = v_product_id;
END$$

DELIMITER ;

